const TEMPLATE = "<!doctype html>\n<html lang=\"pl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>{{subject}}</title>\n</head>\n<body style=\"margin:0;padding:0;background:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#18181b;\">\n<div style=\"display:none;max-height:0;overflow:hidden;\">{{preheader}}</div>\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#f4f4f5;\">\n<tr><td align=\"center\" style=\"padding:24px 12px;\">\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"max-width:640px;background:#ffffff;border-radius:14px;overflow:hidden;\">\n  <tr><td style=\"background:#0f172a;padding:24px 28px;color:#ffffff;\">\n    <div style=\"font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#a5b4fc;\">NEWSFLOW · AI Intelligence Briefing</div>\n    <div style=\"font-size:24px;font-weight:700;margin-top:6px;line-height:1.25;\">{{title}}</div>\n    <div style=\"font-size:14px;color:#cbd5e1;margin-top:6px;\">{{date_long}}</div>\n  </td></tr>\n  {{audio_block}}\n  {{notice_block}}\n  <tr><td style=\"padding:24px 28px 8px;\">\n    <div style=\"font-size:16px;line-height:1.6;color:#27272a;\">{{lead}}</div>\n  </td></tr>\n  {{headline_block}}\n  <tr><td style=\"padding:8px 28px 0;\">\n    <div style=\"font-size:13px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#6366f1;border-bottom:1px solid #e4e4e7;padding-bottom:8px;\">Najważniejsze tematy</div>\n  </td></tr>\n  {{topics_block}}\n  {{trends_block}}\n  <tr><td style=\"padding:20px 28px;\">\n    <table role=\"presentation\" width=\"100%\" style=\"background:#f8fafc;border-radius:10px;\"><tr>\n      <td style=\"padding:14px 16px;font-size:13px;color:#52525b;line-height:1.6;\">\n        Przeanalizowane materiały: <b>{{stats_analyzed}}</b> · Odrzucone: <b>{{stats_rejected}}</b> · Niekompletne: <b>{{stats_incomplete}}</b> · Zebrane (24 h): <b>{{stats_collected}}</b>\n      </td></tr></table>\n  </td></tr>\n  <tr><td style=\"padding:0 28px 28px;font-size:12px;color:#71717a;line-height:1.6;\">\n    <a href=\"{{briefing_link}}\" style=\"color:#4f46e5;\">Otwórz pełny briefing w aplikacji</a><br>\n    Streszczenia i audycja zostały przygotowane automatycznie przez AI na podstawie podlinkowanych źródeł. Głos w nagraniu jest generowany przez AI (ElevenLabs).\n    Sprawdzaj ważne informacje w oryginalnych materiałach.\n  </td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>\n";
const SUPABASE_URL = 'https://YOUR-PROJECT-REF.supabase.co';
const cfg = $('Load config').first().json;
const D = cfg.delivery || {};
const d = $('Prepare delivery').first().json;
const sign = $input.first() ? $input.first().json : {};
const date = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd');
const datePl = $now.setZone('Europe/Warsaw').toFormat('dd.MM.yyyy');
if (!D.email_to || /^REPLACE/.test(D.email_to)) throw new Error('Ustaw app_config.delivery.email_to');

if (d.missing) {
  return [{ json: {
    to: D.email_to, briefing_id: null, status: null,
    subject: `NEWSFLOW – briefing ${datePl} nie został przygotowany`,
    html: `<p>Dzisiejszy briefing (${escapeHtml(formatDatePl(date))}) nie został wygenerowany.</p>
           <p>Sprawdź tabelę <code>pipeline_runs</code> w Supabase oraz historię wykonań WF03/WF04 w n8n.</p>`,
  } }];
}
const audioUrl = d.audio_path && sign && sign.signedURL ? SUPABASE_URL + '/storage/v1' + sign.signedURL : null;
const notice = audioUrl ? null
  : 'Nagranie audio nie zostało dziś wygenerowane — poniżej pełna wersja tekstowa. Szczegóły w pipeline_runs (WF05).';
const { subject, html } = renderBriefingEmail(TEMPLATE, { ...d, briefing_date_pl: datePl }, {
  audioUrl, notice, signedUrlDays: D.signed_url_days || 7,
  briefingLink: (D.app_url_scheme || 'newsflow://') + 'briefing/' + d.briefing_date,
});
return [{ json: { to: D.email_to, subject, html, briefing_id: d.id, status: audioUrl ? 'delivered' : 'delivered_text_only' } }];

